import re
import json
from typing import Any, Dict, List, Tuple, Optional

# --------------------------------------------------------------------
# Helper functions (assumed to be provided in the execution environment)
# --------------------------------------------------------------------
# def node_by_title(doc: dict, title: str) -> dict: ...
# def node_by_id(doc: dict, node_id: str) -> dict: ...
# def children(doc: dict, node: dict) -> List[dict]: ...
# def scope_nodes(doc: dict, scope: str) -> List[dict]: ...
# def table_rows(node: dict) -> List[Tuple[int, Dict[str, str]]]: ...


# --------------------------------------------------------------------
# Parsing utilities
# --------------------------------------------------------------------
def _parse_frame_from_line(line: str) -> Optional[int]:
    """Extract frame number from a line starting with 'Frame X:'."""
    m = re.search(r'^Frame\s+(\d+)\s*:', line)
    return int(m.group(1)) if m else None


def _extract_object_id_from_line(line: str) -> Optional[str]:
    """Extract the object id such as 'Object 3' from the line."""
    m = re.search(r'Object\s+(\d+)', line)
    return f"Object {m.group(1)}" if m else None


def _extract_collision_objects(line: str) -> List[str]:
    """Return list of object ids that are involved in a collision described in this line."""
    return [f"Object {m.group(1)}" for m in re.finditer(r'Object\s+(\d+)', line)]


# --------------------------------------------------------------------
# Main interface functions
# --------------------------------------------------------------------
def entities(doc, scope: str) -> List[Dict[str, Any]]:
    """
    Return all distinct entities mentioned in the scope.
    Each entity has a unique id (e.g. 'Object 0')
    and a human‑readable description.
    """
    res = []
    nodes = scope_nodes(doc, scope)
    for node in nodes:
        if node.get("kind") == "list" and node.get("title", "").endswith(": Objects"):
            for line in node.get("lines", []):
                m = re.match(r'Object\s+(\d+):\s+(.+)', line)
                if m:
                    obj_id = f"Object {m.group(1)}"
                    description = m.group(2).strip()
                    res.append({"id": obj_id, "description": description})
    return res


def recorded_end(doc, scope: str) -> Optional[float]:
    """
    Return the last time point (frame number as float, if any) covered by the records.
    """
    max_frame = None
    nodes = scope_nodes(doc, scope)
    for node in nodes:
        kind = node.get("kind")
        if kind == "list":
            for line in node.get("lines", []):
                frame = _parse_frame_from_line(line)
                if frame is not None:
                    if max_frame is None or frame > max_frame:
                        max_frame = frame
        elif kind == "table":
            for row_index, row in table_rows(node):
                try:
                    frame = int(row.get("frame", 0))
                    if max_frame is None or frame > max_frame:
                        max_frame = frame
                except ValueError:
                    continue
    return float(max_frame) if max_frame is not None else None


def inputs(doc, scope: str) -> List[Dict[str, Any]]:
    """
    Return a list of input records for the given scope.
    Inputs include object arrivals ('enters the scene' or present at video start).
    Each input carries the initial state if available from the motion log.
    """
    inputs = []
    nodes = scope_nodes(doc, scope)
    # Find motion‑log table node for later lookup
    motion_table = None
    for node in nodes:
        if node.get("kind") == "table" and node.get("title", "").endswith(": Motion log"):
            motion_table = node
            break

    # Build quick lookup of motion‑log rows by (frame, object id)
    motion_lookup: Dict[Tuple[int, str], Dict[str, str]] = {}
    if motion_table:
        for row_index, row in table_rows(motion_table):
            try:
                frame = int(row.get("frame", 0))
                obj_desc = row.get("object", "")
                mobj = re.search(r'(\d+)\s', obj_desc)
                if mobj:
                    obj_id = f"Object {mobj.group(1)}"
                    motion_lookup[(frame, obj_id)] = row
            except ValueError:
                continue

    # Process event list for arrivals
    for node in nodes:
        if node.get("kind") == "list" and node.get("title", "").endswith(": Events"):
            for line_index, line in enumerate(node.get("lines", [])):
                if "enters the scene" in line or "is in view when the video begins" in line:
                    frame = _parse_frame_from_line(line)
                    if frame is None:
                        continue
                    obj_id = _extract_object_id_from_line(line)
                    if not obj_id:
                        continue

                    # Gather fields from motion log at that frame, if available
                    fields = {}
                    motion_row = motion_lookup.get((frame, obj_id))
                    if motion_row:
                        for col in ("x", "y", "vx", "vy", "speed"):
                            val = motion_row.get(col)
                            if val is not None and val != "":
                                try:
                                    fields[col] = float(val)
                                except ValueError:
                                    fields[col] = val

                    input_id = f"arrival_{obj_id.replace(' ','_')}_{frame}"
                    inputs.append({
                        "id": input_id,
                        "time": float(frame),
                        "kind": "arrival",
                        "entities": [obj_id],
                        "fields": fields,
                        "src": [
                            [node.get("node_id"), line_index],
                            [motion_table.get("node_id") if motion_table else None, None] if motion_row else None
                        ],
                    })
    # Filter out None src entries
    for inp in inputs:
        inp["src"] = [s for s in inp["src"] if s]
    return inputs


def outcomes(doc, scope: str) -> List[Dict[str, Any]]:
    """
    Return a list of outcome records for the given scope.
    Outcomes include collisions ('collides with') and exits ('exits the scene').
    """
    outcomes = []
    nodes = scope_nodes(doc, scope)
    # Find motion‑log table node for potential src reference
    motion_table = None
    for node in nodes:
        if node.get("kind") == "table" and node.get("title", "").endswith(": Motion log"):
            motion_table = node
            break
    for node in nodes:
        if node.get("kind") == "list" and node.get("title", "").endswith(": Events"):
            for line_index, line in enumerate(node.get("lines", [])):
                frame = _parse_frame_from_line(line)
                if frame is None:
                    continue
                # Collision event
                if "collides with" in line:
                    obj_ids = _extract_collision_objects(line)
                    outcome_id = f"collision_{obj_ids[0].replace(' ','_')}_{obj_ids[1].replace(' ','_')}_{frame}"
                    outcomes.append({
                        "time": float(frame),
                        "kind": "collision",
                        "entities": obj_ids,
                        "value": None,
                        "src": [[node.get("node_id"), line_index]],
                    })
                # Exit event
                elif "exits the scene" in line:
                    obj_id = _extract_object_id_from_line(line)
                    if obj_id:
                        outcome_id = f"exit_{obj_id.replace(' ','_')}_{frame}"
                        outcomes.append({
                            "time": float(frame),
                            "kind": "exit",
                            "entities": [obj_id],
                            "value": None,
                            "src": [[node.get("node_id"), line_index]],
                        })
    return outcomes


def params(doc, scope: str) -> Dict[str, Any]:
    """
    Return constants if any. The document does not specify any constants,
    so the function returns an empty dict.
    """
    return {}

import re
from typing import Any, Dict, List, Tuple, Optional

