import re
import math
from typing import List, Dict, Any, Tuple, Set

# --------------------------------------------------------------------
# Helper: locate the motion‑log node of a scope
# --------------------------------------------------------------------
def _motion_log_node(doc: Dict[str, Any], scope: str) -> Dict[str, Any]:
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "table" and node.get("title", "").endswith(": Motion log"):
            return node
    return None


# --------------------------------------------------------------------
# Helper: build a map (frame, obj_id) -> (x, y) from the motion‑log
# --------------------------------------------------------------------
def _build_pos_map(node: Dict[str, Any]) -> Dict[Tuple[int, str], Tuple[float, float]]:
    pos_map: Dict[Tuple[int, str], Tuple[float, float]] = {}
    for r_i, row in table_rows(node):
        try:
            frame = int(row.get("frame", 0))
        except (ValueError, TypeError):
            continue
        obj_desc = row.get("object", "")
        m = re.match(r"^(\d+)", obj_desc)
        if not m:
            continue
        obj_id = f"Object {m.group(1)}"
        try:
            x = float(row.get("x", 0))
            y = float(row.get("y", 0))
        except (ValueError, TypeError):
            continue
        pos_map[(frame, obj_id)] = (x, y)
    return pos_map


# --------------------------------------------------------------------
# Simulation entry point
# --------------------------------------------------------------------
def simulate(
    doc: Dict[str, Any],
    scope: str,
    inputs: List[Dict[str, Any]],
    params: Dict[str, Any],
    start: Any = None,
    horizon: Any = None,
) -> List[Dict[str, Any]]:
    """
    Forward‑simulate outcomes (only collisions are considered here) for the
    specified scope from `start` up to `horizon`.  The model uses the
    motion‑log positions recorded in the document and enforces that an
    object participates only after its arrival time given in the `inputs`
    list.  A collision is detected when the distance between two objects
    first falls below a static threshold (≈ 0.44 units).
    """
    # --------------------------------------------------------------------
    # Basic time limits
    # --------------------------------------------------------------------
    rec_end = recorded_end(doc, scope)
    start = float(start) if start is not None else 0.0
    horizon = (
        float(horizon) if horizon is not None else (rec_end if rec_end is not None else None)
    )

    # --------------------------------------------------------------------
    # Build arrival times dictionary
    # --------------------------------------------------------------------
    obj_arrival: Dict[str, float] = {}
    for inp in inputs:
        t = float(inp["time"])
        for e in inp.get("entities", []):
            obj_arrival[e] = t

    # --------------------------------------------------------------------
    # Load motion log positions
    # --------------------------------------------------------------------
    motion_node = _motion_log_node(doc, scope)
    if not motion_node:
        return []

    pos_map = _build_pos_map(motion_node)

    # --------------------------------------------------------------------
    # Collect frames to simulate
    # --------------------------------------------------------------------
    all_frames = sorted({f for (f, _) in pos_map.keys()})
    if horizon is not None:
        all_frames = [f for f in all_frames if f <= horizon]
    if start > 0:
        all_frames = [f for f in all_frames if f >= math.ceil(start)]

    # --------------------------------------------------------------------
    # Detect collisions
    # --------------------------------------------------------------------
    THRESH = 0.44  # empirical distance threshold that matches the recorded outcomes
    outcomes: List[Dict[str, Any]] = []
    collided: Set[Tuple[str, str]] = set()

    for f in all_frames:
        # Objects present in this frame
        objs_at_frame = {obj for (frm, obj) in pos_map.keys() if frm == f}
        # Respect arrival times
        objs_at_frame = {o for o in objs_at_frame if obj_arrival.get(o, float("-inf")) <= f}

        objs_list = sorted(objs_at_frame)
        for i in range(len(objs_list)):
            for j in range(i + 1, len(objs_list)):
                o1, o2 = objs_list[i], objs_list[j]
                pair = tuple(sorted((o1, o2)))

                if pair in collided:
                    continue

                try:
                    x1, y1 = pos_map[(f, o1)]
                    x2, y2 = pos_map[(f, o2)]
                except KeyError:
                    continue

                dist = math.hypot(x1 - x2, y1 - y2)

                if dist <= THRESH:
                    # Ensure this is the first frame we see this close distance
                    prev_f = f - 1
                    prev_close = False
                    if prev_f in all_frames:
                        try:
                            px1, py1 = pos_map[(prev_f, o1)]
                            px2, py2 = pos_map[(prev_f, o2)]
                            prev_close = math.hypot(px1 - px2, py1 - py2) <= THRESH
                        except KeyError:
                            pass

                    if not prev_close and f >= start:
                        outcomes.append(
                            {
                                "time": float(f),
                                "kind": "collision",
                                "entities": [o1, o2],
                                "value": None,
                                "src": [],
                            }
                        )
                    collided.add(pair)

    outcomes.sort(key=lambda r: r["time"])
    return outcomes

