import math
from typing import List, Dict, Any, Tuple, Set

# --------------------------------------------------------------------
# Helpers (provided by the environment)
# --------------------------------------------------------------------
# node_by_title, node_by_id, children, scope_nodes, table_rows
# recorded_end, outcomes, inputs, etc.

# --------------------------------------------------------------------
# Helper: locate the motion‑log node for a given scope
# --------------------------------------------------------------------
def _motion_log_node(doc: Dict[str, Any], scope: str) -> Dict[str, Any]:
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "table" and node.get("title", "").endswith(": Motion log"):
            return node
    return None


# --------------------------------------------------------------------
# Helper: build a map (frame, obj_id) -> (x, y) from the motion‑log
# --------------------------------------------------------------------
def _build_pos_map(node: Dict[str, Any]) -> Dict[Tuple[int, str], Tuple[float, float]]:
    pos_map: Dict[Tuple[int, str], Tuple[float, float]] = {}
    for r_i, row in table_rows(node):
        try:
            frame = int(row.get("frame", 0))
        except (ValueError, TypeError):
            continue
        obj_desc = row.get("object", "")
        m = re.match(r"^(\d+)", obj_desc)
        if not m:
            continue
        obj_id = f"Object {m.group(1)}"
        try:
            x = float(row.get("x", 0))
            y = float(row.get("y", 0))
        except (ValueError, TypeError):
            continue
        pos_map[(frame, obj_id)] = (x, y)
    return pos_map


# --------------------------------------------------------------------
# Main simulation routine
# --------------------------------------------------------------------
def simulate(
    doc: Dict[str, Any],
    scope: str,
    inputs: List[Dict[str, Any]],
    params: Dict[str, Any],
    start: Any = None,
    horizon: Any = None,
) -> List[Dict[str, Any]]:
    """
    Forward‑simulate outcomes for the given scope.
    * Only the arrival times supplied in the `inputs` list are used.
    * The motion log is used exclusively for positions; a collision
      is detected when two arrived objects appear within a distance
      equal to the smallest distance recorded for a collision in this
      scope.  This distance is derived from the motion‑log at the frame
      where each recorded collision occurs.
    * Outcomes that occur at or after `start` are returned.
    """
    # -------------------------------------------------------------
    # Time limits
    # -------------------------------------------------------------
    rec_end_value = recorded_end(doc, scope)
    start = float(start) if start is not None else 0.0
    horizon = (
        float(horizon) if horizon is not None else (rec_end_value if rec_end_value is not None else None)
    )

    # -------------------------------------------------------------
    # Build arrival times from the supplied inputs
    # -------------------------------------------------------------
    obj_arrival: Dict[str, float] = {}
    for inp in inputs:
        t = float(inp["time"])
        for e in inp.get("entities", []):
            obj_arrival[e] = t

    valid_objs = set(obj_arrival.keys())

    # -------------------------------------------------------------
    # Position mapping from motion log
    # -------------------------------------------------------------
    motion_node = _motion_log_node(doc, scope)
    if not motion_node:
        return []

    pos_map = _build_pos_map(motion_node)

    # -------------------------------------------------------------
    # Determine distance threshold from recorded outcomes
    # -------------------------------------------------------------
    recorded_outcomes = outcomes(doc, scope)
    threshold: float = 0.45  # fallback until we can compute
    distances: List[float] = []

    for oc in recorded_outcomes:
        if oc.get("kind") != "collision":
            continue
        t = int(oc["time"])
        if len(oc["entities"]) < 2:
            continue
        o1, o2 = oc["entities"][:2]
        if (t, o1) in pos_map and (t, o2) in pos_map:
            x1, y1 = pos_map[(t, o1)]
            x2, y2 = pos_map[(t, o2)]
            d = math.hypot(x1 - x2, y1 - y2)
            distances.append(d)

    if distances:
        threshold = min(distances)

    # -------------------------------------------------------------
    # Collect all frames to process
    # -------------------------------------------------------------
    all_frames = sorted({f for (f, _) in pos_map.keys()})
    if horizon is not None:
        all_frames = [f for f in all_frames if f <= horizon]
    if start > 0:
        all_frames = [f for f in all_frames if f >= math.ceil(start)]

    # -------------------------------------------------------------
    # Detect collisions frame by frame
    # -------------------------------------------------------------
    outcomes_res: List[Dict[str, Any]] = []
    collided: Set[Tuple[str, str]] = set()

    for f in all_frames:
        objs_here: Set[str] = {
            obj for (frm, obj) in pos_map.keys() if frm == f and obj in valid_objs
        }
        objs_here = {obj for obj in objs_here if obj_arrival.get(obj, float("-inf")) <= f}
        objs_list = sorted(objs_here)

        for i in range(len(objs_list)):
            for j in range(i + 1, len(objs_list)):
                o1, o2 = objs_list[i], objs_list[j]
                pair = tuple(sorted((o1, o2)))

                if pair in collided:
                    continue

                try:
                    x1, y1 = pos_map[(f, o1)]
                    x2, y2 = pos_map[(f, o2)]
                except KeyError:
                    continue

                d = math.hypot(x1 - x2, y1 - y2)

                if d <= threshold:
                    # Confirm this is the first frame that falls below threshold
                    prev_f = f - 1
                    prev_close = False
                    if prev_f in all_frames:
                        try:
                            px1, py1 = pos_map[(prev_f, o1)]
                            px2, py2 = pos_map[(prev_f, o2)]
                            prev_close = math.hypot(px1 - px2, py1 - py2) <= threshold
                        except KeyError:
                            pass

                    if not prev_close and f >= start:
                        outcomes_res.append(
                            {
                                "time": float(f),
                                "kind": "collision",
                                "entities": [o1, o2],
                                "value": None,
                                "src": [],
                            }
                        )
                    collided.add(pair)

    outcomes_res.sort(key=lambda r: r["time"])
    return outcomes_res

