    # Fall back to a generous default if none are available.
    threshold = max(distances) if distances else 1.0

    # ----- Compile list of frames to process --------------------------------
    all_frames = sorted({f for (f, _) in pos_map.keys()})
    if horizon is not None:
        all_frames = [f for f in all_frames if f <= horizon]
    if start > 0:
        all_frames = [f for f in all_frames if f >= math.ceil(start)]

    # ----- Detect collisions frame by frame --------------------------------
    outcomes_res: List[Dict[str, Any]] = []
    collided: Set[Tuple[str, str]] = set()

    for f in all_frames:
        # Objects present at this frame that have an arrival record
        objs_here = {
            obj for (frm, obj) in pos_map.keys() if frm == f and obj in valid_objs
        }
        # Keep only those that have actually arrived by this time
        objs_here = {obj for obj in objs_here if obj_arrival.get(obj, float("-inf")) <= f}

        objs_list = sorted(objs_here)

        for i in range(len(objs_list)):
            for j in range(i + 1, len(objs_list)):
                o1, o2 = objs_list[i], objs_list[j]
                pair = tuple(sorted((o1, o2)))

                if pair in collided:
                    continue

                try:
                    x1, y1 = pos_map[(f, o1)]
                    x2, y2 = pos_map[(f, o2)]
                except KeyError:
                    continue

                d = math.hypot(x1 - x2, y1 - y2)

                if d <= threshold:
                    # Ensure this is the first frame below threshold
                    prev_f = f - 1
                    prev_close = False
                    if prev_f in all_frames:
                        try:
                            px1, py1 = pos_map[(prev_f, o1)]
                            px2, py2 = pos_map[(prev_f, o2)]
                            prev_close = math.hypot(px1 - px2, py1 - py2) <= threshold
                        except KeyError:
                            pass

                    if not prev_close and f >= start:
                        outcomes_res.append(
                            {
                                "time": float(f),
                                "kind": "collision",
                                "entities": [o1, o2],
                                "value": None,
                                "src": [],
                            }
                        )
                    collided.add(pair)

    outcomes_res.sort(key=lambda r: r["time"])
    return outcomes_res

