import math
from dataclasses import dataclass
from typing import Dict, List, Tuple, Any

# ----------------------------------------------------------------------
# Helper dataclass for object state, including the last arrival time
# ----------------------------------------------------------------------
@dataclass
class Body:
    id: str
    pos: Tuple[float, float]
    vel: Tuple[float, float]
    arrival: float      # time when this object's last arrival event happened


# ----------------------------------------------------------------------
# Core helper utilities
# ----------------------------------------------------------------------
def _build_bodies(inputs: List[Dict[str, Any]]) -> Dict[str, Body]:
    """Create bodies from the arrival inputs, keeping the last arrival for each."""
    bodies: Dict[str, Body] = {}
    for inp in sorted(inputs, key=lambda x: x["time"]):
        t = inp["time"]
        bid = inp["entities"][0]
        bodies[bid] = Body(
            id=bid,
            pos=(inp["fields"]["x"], inp["fields"]["y"]),
            vel=(inp["fields"]["vx"], inp["fields"]["vy"]),
            arrival=t,
        )
    return bodies


def _advance(bodies: Dict[str, Body], dt: float) -> None:
    """Move all bodies forward by dt."""
    for b in bodies.values():
        b.pos = (b.pos[0] + b.vel[0] * dt, b.pos[1] + b.vel[1] * dt)


def _distance(p1: Tuple[float, float], p2: Tuple[float, float]) -> float:
    return math.hypot(p2[0] - p1[0], p2[1] - p1[1])


def _time_to_collision(b1: Body, b2: Body, R: float = 0.5, eps: float = 1e-9) -> float | None:
    """
    Return time until collision for two equal‑mass spheres of radius R.
    If already overlapping, return 0.0 to indicate an immediate collision.
    """
    d0 = _distance(b1.pos, b2.pos)
    if d0 <= 2 * R + eps:
        return 0.0

    r0 = (b2.pos[0] - b1.pos[0], b2.pos[1] - b1.pos[1])
    dv = (b2.vel[0] - b1.vel[0], b2.vel[1] - b1.vel[1])

    a = dv[0] ** 2 + dv[1] ** 2
    if a < eps:
        return None
    bcoef = 2 * (r0[0] * dv[0] + r0[1] * dv[1])
    c = r0[0] ** 2 + r0[1] ** 2 - (2 * R) ** 2

    disc = bcoef * bcoef - 4 * a * c
    if disc < 0:
        return None
    sqrt_disc = math.sqrt(disc)
    t1 = (-bcoef - sqrt_disc) / (2 * a)
    t2 = (-bcoef + sqrt_disc) / (2 * a)

    candidates = [t for t in (t1, t2) if t > eps]
    return min(candidates) if candidates else None


def _apply_collision_full_exchange(b1: Body, b2: Body) -> None:
    """
    Swap the full velocity vectors of the two bodies to mimic an equal‑mass elastic
    collision when the interaction is dominated by geometry (no friction).
    """
    b1.vel, b2.vel = b2.vel, b1.vel


# ----------------------------------------------------------------------
# Main simulation function
# ----------------------------------------------------------------------
def simulate(doc: Dict[str, Any], scope: str, inputs: List[Dict[str, Any]],
             params: Dict[str, Any] = {}, start: float = None,
             horizon: float = None) -> List[Dict[str, Any]]:
    """
    Forward‐model CLEVRER videos.  The model keeps:
      * Constant velocity motion until an event.
      * Full velocity exchange at each collision (equal masses).
      * Objects enter at their arrival timestamps; unseen before.
      * Exits are ignored.
    """
    if start is None:
        start = 0.0
    rec_end = recorded_end(doc, scope)
    if horizon is None:
        horizon = rec_end if rec_end is not None else math.inf

    # Prepare bodies from inputs
    all_bodies = _build_bodies(inputs)          # all known bodies
    active: Dict[str, Body] = {}                # bodies that are currently in the scene

    # Advance bodies that arrived before start
    for bid, body in all_bodies.items():
        if body.arrival > start:
            continue
        dt = start - body.arrival
        body.pos = (body.pos[0] + body.vel[0] * dt,
                    body.pos[1] + body.vel[1] * dt)
        active[bid] = body

    current = start
    outcomes: List[Dict[str, Any]] = []

    # Main loop: decide next event (arrival or collision)
    while current < horizon:
        # next arrival after current
        next_arrival_time = None
        next_arrival_body: Body | None = None
        for bid, body in all_bodies.items():
            if bid in active:
                continue
            if body.arrival > current and (next_arrival_time is None or body.arrival < next_arrival_time):
                next_arrival_time = body.arrival
                next_arrival_body = body

        # earliest collision among active bodies
        next_collision_time = None
        coll_pair: Tuple[Body, Body] | None = None
        ids = list(active.keys())
        for i in range(len(ids)):
            for j in range(i + 1, len(ids)):
                b1 = active[ids[i]]
                b2 = active[ids[j]]
                t_rel = _time_to_collision(b1, b2)
                if t_rel is None:
                    continue
                t_abs = current + t_rel
                if t_abs <= current:
                    t_abs = current  # overlapping immediately
                if next_collision_time is None or t_abs < next_collision_time:
                    next_collision_time = t_abs
                    coll_pair = (b1, b2)

        # No events: break
        if next_arrival_time is None and next_collision_time is None:
            break

        # Decide which event occurs first
        event_time, event_type = None, None
        if next_arrival_time is not None and (next_collision_time is None or next_arrival_time <= next_collision_time):
            event_time = next_arrival_time
            event_type = "arrival"
        else:
            event_time = next_collision_time
            event_type = "collision"

        # Advance to that time
        dt = event_time - current
        _advance(active, dt)
        current = event_time

        if event_type == "arrival" and next_arrival_body:
            active[next_arrival_body.id] = next_arrival_body
        elif event_type == "collision" and coll_pair:
            b1, b2 = coll_pair
            # Record outcome
            occ = {
                "time": current,
                "kind": "collision",
                "entities": [b1.id, b2.id],
                "value": None,
                "src": [],
            }
            outcomes.append(occ)
            # Apply full velocity exchange
            _apply_collision_full_exchange(b1, b2)

        # If reached horizon, exit
        if current >= horizon:
            break

    return outcomes

