import math
from dataclasses import dataclass
from typing import Dict, List, Tuple, Any

# ----------------------------------------------------------------------
# Object state
# ----------------------------------------------------------------------
@dataclass
class Body:
    id: str
    pos: Tuple[float, float]
    vel: Tuple[float, float]
    arrival: float   # time of last arrival event


# ----------------------------------------------------------------------
# Helper functions
# ----------------------------------------------------------------------
def _build_bodies(inputs: List[Dict[str, Any]]) -> Dict[str, Body]:
    """Create a body for each arrival, keeping the newest record."""
    bodies: Dict[str, Body] = {}
    for inp in sorted(inputs, key=lambda x: x["time"]):
        t = inp["time"]
        bid = inp["entities"][0]
        bodies[bid] = Body(
            id=bid,
            pos=(inp["fields"]["x"], inp["fields"]["y"]),
            vel=(inp["fields"]["vx"], inp["fields"]["vy"]),
            arrival=t,
        )
    return bodies


def _advance(bodies: Dict[str, Body], dt: float) -> None:
    """Advance all active bodies by dt."""
    for b in bodies.values():
        b.pos = (b.pos[0] + b.vel[0] * dt, b.pos[1] + b.vel[1] * dt)


def _distance(p1: Tuple[float, float], p2: Tuple[float, float]) -> float:
    return math.hypot(p2[0] - p1[0], p2[1] - p1[1])


def _time_to_collision(b1: Body, b2: Body, R: float = 0.5, eps: float = 1e-9) -> float | None:
    """Time until collision of two equal‑mass spheres of radius R."""
    d0 = _distance(b1.pos, b2.pos)
    if d0 <= 2 * R + eps:
        return 0.0  # already touching

    r0 = (b2.pos[0] - b1.pos[0], b2.pos[1] - b1.pos[1])
    dv = (b2.vel[0] - b1.vel[0], b2.vel[1] - b1.vel[1])

    a = dv[0] ** 2 + dv[1] ** 2
    if a < eps:
        return None
    bcoef = 2 * (r0[0] * dv[0] + r0[1] * dv[1])
    c = r0[0] ** 2 + r0[1] ** 2 - (2 * R) ** 2

    disc = bcoef * bcoef - 4 * a * c
    if disc < 0:
        return None
    sqrt_disc = math.sqrt(disc)
    t1 = (-bcoef - sqrt_disc) / (2 * a)
    t2 = (-bcoef + sqrt_disc) / (2 * a)

    candidates = [t for t in (t1, t2) if t > eps]
    return min(candidates) if candidates else None


def _apply_collision(b1: Body, b2: Body) -> None:
    """
    Exchange the entire velocity vectors (approximate equal‑mass elastic collision).
    """
    b1.vel, b2.vel = b2.vel, b1.vel


# ----------------------------------------------------------------------
# Main simulation
# ----------------------------------------------------------------------
def simulate(doc: Dict[str, Any], scope: str, inputs: List[Dict[str, Any]],
             params: Dict[str, Any] = {}, start: float = None,
             horizon: float = None) -> List[Dict[str, Any]]:
    """
    Forward simulation of CLEVRER videos.  Objects move with constant velocity
    until they collide; at a collision their velocities are swapped (equal masses).
    Objects appear at the timestamp of their last arrival.  Exits are ignored.
    """
    if start is None:
        start = 0.0
    rec_end = recorded_end(doc, scope)
    if horizon is None:
        horizon = rec_end if rec_end is not None else math.inf

    # Build all bodies
    all_bodies = _build_bodies(inputs)
    active: Dict[str, Body] = {}

    # Bring bodies that had already arrived to time 'start'
    for bid, body in all_bodies.items():
        if body.arrival > start:
            continue
        dt = start - body.arrival
        body.pos = (body.pos[0] + body.vel[0] * dt,
                    body.pos[1] + body.vel[1] * dt)
        active[bid] = body

    current = start
    outcomes: List[Dict[str, Any]] = []

    max_events = 10000  # safeguard against infinite loops
    events_processed = 0

    while current < horizon and events_processed < max_events:
        # Determine next arrival after current
        next_arrival_time: float | None = None
        next_arrival_body: Body | None = None
        for bid, body in all_bodies.items():
            if bid in active:
                continue
            if body.arrival > current and (next_arrival_time is None or body.arrival < next_arrival_time):
                next_arrival_time = body.arrival
                next_arrival_body = body

        # Determine next collision among active bodies
        next_collision_time: float | None = None
        coll_pair: Tuple[Body, Body] | None = None
        ids = list(active.keys())
        for i in range(len(ids)):
            for j in range(i + 1, len(ids)):
                b1 = active[ids[i]]
                b2 = active[ids[j]]
                t_rel = _time_to_collision(b1, b2)
                if t_rel is None:
                    continue
                t_abs = current + t_rel
                # Ignore collisions that already happened in past numerics
                if t_abs <= current + 1e-9:
                    t_abs = current
                if next_collision_time is None or t_abs < next_collision_time:
                    next_collision_time = t_abs
                    coll_pair = (b1, b2)

        # If no future events, break
        if next_arrival_time is None and next_collision_time is None:
            break

        # Pick earliest event
        event_time = None
        event_type: str | None = None
        if next_arrival_time is None:
            event_time = next_collision_time
            event_type = "collision"
        elif next_collision_time is None:
            event_time = next_arrival_time
            event_type = "arrival"
        else:
            if next_arrival_time <= next_collision_time:
                event_time = next_arrival_time
                event_type = "arrival"
            else:
                event_time = next_collision_time
                event_type = "collision"

        # Advance time
        dt = event_time - current
        if dt > 0:
            _advance(active, dt)
            current = event_time
        else:
            # dt == 0: event occurs immediately; still count as processed
            # but do not advance
            pass

        # Process event
        if event_type == "arrival" and next_arrival_body:
            active[next_arrival_body.id] = next_arrival_body
        elif event_type == "collision" and coll_pair:
            b1, b2 = coll_pair
            outcome = {
                "time": current,
                "kind": "collision",
                "entities": [b1.id, b2.id],
                "value": None,
                "src": [],
            }
            outcomes.append(outcome)
            _apply_collision(b1, b2)

        events_processed += 1

    return outcomes

