def _get_collision_distance(doc: Dict[str, Any], params: Dict[str, Any]) -> float:
    """Estimate a realistic collision threshold from recorded data."""
    thresholds = []
    for node in doc.get("nodes", []):
        if node.get("kind") != "table" or not node.get("title", "").endswith(": Motion log"):
            continue
        scope_name = node["title"].split(":")[0]
        scope_node = node_by_title(doc, scope_name)
        if not scope_node:
            continue
        events_node = next((c for c in children(doc, scope_node)
                            if c.get("kind") == "list" and c.get("title", "").endswith(": Events")),
                           None)
        if not events_node:
            continue
        pos_lookup: Dict[Tuple[int, str], Tuple[float, float]] = {}
        for r_i, row in table_rows(node):
            try:
                f = int(row["frame"])
                m = re.match(r"(\d+)\s", row["object"])
                if m:
                    oid = f"Object {m.group(1)}"
                    pos_lookup[(f, oid)] = (float(row["x"]), float(row["y"]))
            except Exception:
                pass
        for line in events_node.get("lines", []):
            if "collides with" not in line:
                continue
            f = _frame_from_line(line)
            if f is None:
                continue
            objs = _obj_ids_from_line(line)
            if len(objs) < 2:
                continue
            pts = [pos_lookup.get((f, o)) for o in objs]
            if len(pts) < 2:
                for shift in (-1, 1):
                    pts = [pos_lookup.get((f + shift, o)) for o in objs]
                    if len(pts) == 2:
                        break
            if len(pts) == 2:
                thresholds.append(math.dist(pts[0], pts[1]))
    if thresholds:
        thresholds.sort()
        median = thresholds[len(thresholds)//2]
        return median * 1.2
    return 0.1

# --------------------------------------------------------------------
def simulate(doc, scope, inputs, params, start=None, horizon=None) -> List[Dict[str, Any]]:
    """
    Forward‐model that predicts collisions for a CLEVRER video.
    """
    # 1. Build state from arrival records
    state: Dict[str, Dict[str, Any]] = {}
    for inp in inputs:
        if inp["kind"] != "arrival":
            continue
        oid = inp["entities"][0]
        t = inp["time"]
        flds = inp.get("fields", {})
        state[oid] = {
            "time": t,
            "pos": (flds.get("x", 0.0), flds.get("y", 0.0)),
            "vel": (flds.get("vx", 0.0), flds.get("vy", 0.0)),
        }

    # 2. Determine simulation bounds
    rec_end = recorded_end(doc, scope)
    if start is None:
        start = min(i["time"] for i in inputs) if inputs else 0.0
    if horizon is None:
        horizon = rec_end if rec_end is not None else start + 100.0

    # 3. Keep only objects that existed before `start`
    for oid in list(state.keys()):
        if state[oid]["time"] > start:
            del state[oid]

    active_ids = {inp["entities"][0] for inp in inputs if inp["kind"] == "arrival"}

    # 4. Collision threshold
    COLLIDE_DIST = _get_collision_distance(doc, params)

    # 5. Helper: position at arbitrary time
    def pos_at(oid: str, t_now: float) -> Optional[Tuple[float, float]]:
        st = state.get(oid)
        if not st:
            return None
        delta = t_now - st["time"]
        if delta < 0:
            return None
        return (st["pos"][0] + st["vel"][0] * delta,
                st["pos"][1] + st["vel"][1] * delta)

    # 6. Sweep through time to detect collisions
    dt = 0.5
    steps = int(math.ceil((horizon - start) / dt)) + 1
    events: List[Dict[str, Any]] = []
    checked_pairs = set()

    for step in range(steps):
        t_now = start + step * dt
        if t_now > horizon:
            break
        pos_now = {oid: pos_at(oid, t_now) for oid in active_ids if pos_at(oid, t_now) is not None}
        oid_list = sorted(pos_now.keys())
        for i, o1 in enumerate(oid_list):
            for o2 in oid_list[i+1:]:
                pair = (o1, o2)
                if pair in checked_pairs:
                    continue
                d = math.dist(pos_now[o1], pos_now[o2])
                if d <= COLLIDE_DIST:
                    events.append({
                        "time": t_now,
                        "kind": "collision",
                        "entities": list(pair),
                        "value": None,
                        "src": []
                    })
                    checked_pairs.add(pair)

    # 7. Return the outcome list
    events.sort(key=lambda e: e["time"])
    out = []
    for ev in events:
        eid = f"collision_{'_'.join(ev['entities'])}_{int(round(ev['time']))}"
        out.append({
            "id": eid,
            "time": ev["time"],
            "kind": ev["kind"],
            "entities": ev["entities"],
            "value": ev["value"],
            "src": ev["src"]
        })
    return out

