# --------------------------------------------------------------------
# Forward model for CLEVRER videos – predicts the collision outcomes.
# --------------------------------------------------------------------
import math
from typing import Dict, List, Any, Tuple, Optional

# --------------------------------------------------------------------
# Compute a collision threshold from the full document
# --------------------------------------------------------------------
def _get_collision_distance(doc: Dict[str, Any], params: Dict[str, Any]) -> float:
    thresholds = []
    for node in doc.get("nodes", []):
        if node.get("kind") != "table" or not node.get("title", "").endswith(": Motion log"):
            continue
        scope_name = node["title"].split(":")[0]
        scope_node = node_by_title(doc, scope_name)
        if not scope_node:
            continue
        events_node = next((c for c in children(doc, scope_node)
                            if c.get("kind") == "list" and c.get("title", "").endswith(": Events")),
                           None)
        if not events_node:
            continue
        pos_lookup: Dict[Tuple[int, str], Tuple[float, float]] = {}
        for r_i, row in table_rows(node):
            try:
                f = int(row["frame"])
                m = re.match(r"(\d+)\s", row["object"])
                if m:
                    oid = f"Object {m.group(1)}"
                    pos_lookup[(f, oid)] = (float(row["x"]), float(row["y"]))
            except Exception:
                pass
        for line in events_node.get("lines", []):
            if "collides with" not in line:
                continue
            f = _frame_from_line(line)
            if f is None:
                continue
            objs = _obj_ids_from_line(line)
            if len(objs) < 2:
                continue
            pts = [pos_lookup.get((f, o)) for o in objs]
            if len(pts) < 2:
                for shift in (-1, 1):
                    pts = [pos_lookup.get((f + shift, o)) for o in objs]
                    if len(pts) == 2:
                        break
            if len(pts) == 2:
                thresholds.append(math.dist(pts[0], pts[1]))
    if thresholds:
        thresholds.sort()
        median = thresholds[len(thresholds)//2]
        return median * 1.2
    return 0.1

# --------------------------------------------------------------------
def simulate(doc, scope, inputs, params, start=None, horizon=None) -> List[Dict[str, Any]]:
    """Predict collision events for a CLEVRER video using only the supplied
    inputs.  Objects move in straight lines at constant velocity.  A
    collision is declared the first instant two objects come within a
    collision radius estimated from the entire benchmark."""
    # Build mapping: object → (arrival time, pos, vel)
    arrivals: Dict[str, Tuple[float, Tuple[float, float], Tuple[float, float]]] = {}
    for inp in inputs:
        if inp["kind"] != "arrival":
            continue
        oid = inp["entities"][0]
        t = inp["time"]
        flds = inp.get("fields", {})
        arrivals[oid] = (t,
                         (flds.get("x", 0.0), flds.get("y", 0.0)),
                         (flds.get("vx", 0.0), flds.get("vy", 0.0)))

    # Set simulation bounds
    rec_end = recorded_end(doc, scope)
    if start is None:
        start = min(a[0] for a in arrivals.values()) if arrivals else 0.0
    if horizon is None:
        horizon = rec_end if rec_end is not None else start + 100.0

    # Collision radius
    R = _get_collision_distance(doc, params)

    # Helper to compute time of collision for a pair
    def collision_time(o1: str, o2: str) -> Optional[float]:
        t1, p1, v1 = arrivals[o1]
        t2, p2, v2 = arrivals[o2]
        t_low = max(t1, t2)          # both must have arrived
        if t_low > horizon:
            return None

        # Shift time origin to t_low
        # positions at t_low:
        p1_lt = (p1[0] + v1[0] * (t_low - t1), p1[1] + v1[1] * (t_low - t1))
        p2_lt = (p2[0] + v2[0] * (t_low - t2), p2[1] + v2[1] * (t_low - t2))

        dp = (p1_lt[0] - p2_lt[0], p1_lt[1] - p2_lt[1])
        dv = (v1[0] - v2[0], v1[1] - v2[1])

        a = dv[0]**2 + dv[1]**2
        b = 2 * (dp[0]*dv[0] + dp[1]*dv[1])
        c = dp[0]**2 + dp[1]**2 - R**2

        if a == 0:        # parallel equal velocities
            if c <= 0:
                return t_low   # already overlapping
            return None

        disc = b*b - 4*a*c
        if disc < 0:
            return None
        sqrt_disc = math.sqrt(disc)
        t1_root = (-b - sqrt_disc) / (2*a)
        t2_root = (-b + sqrt_disc) / (2*a)

        # we need the smallest root >= 0
        candidate = None
        if t1_root >= 0:
            candidate = t1_root
        elif t2_root >= 0:
            candidate = t2_root
        if candidate is None:
            return None

        collision_strength = t_low + candidate
        if collision_strength < start or collision_strength > horizon:
            return None
        return collision_strength

    # Find all candidate pairs
    obj_keys = list(arrivals.keys())
    events = []
    for i in range(len(obj_keys)):
        for j in range(i+1, len(obj_keys)):
            o1, o2 = obj_keys[i], obj_keys[j]
            t_coll = collision_time(o1, o2)
            if t_coll is not None:
                events.append((t_coll, sorted([o1, o2])))

    # Sort and build outcome records
    events.sort(key=lambda e: e[0])
    outcomes = []
    for t, pair in events:
        if t < start:
            continue
        outcomes.append({
            "time": t,
            "kind": "collision",
            "entities": pair,
            "value": None,
            "src": []
        })

    # Assign ids consistent with expected format
    final = []
    for ev in outcomes:
        eid = f"collision_{'_'.join(ev['entities'])}_{int(round(ev['time']))}"
        final.append({
            "id": eid,
            "time": ev["time"],
            "kind": ev["kind"],
            "entities": ev["entities"],
            "value": ev["value"],
            "src": ev["src"]
        })
    return final

