# --------------------------------------------------------------------
# Forward model for CLEVRER videos – predicts collisions using a
# simplified constant‑velocity motion and a tuned collision radius.
# --------------------------------------------------------------------
import math
from typing import Dict, List, Any, Tuple, Optional

# --------------------------------------------------------------
# Collision radius: a small fixed value that matches the CLEVRER
# dataset (objects are circles/spheres with radius ≈0.1).
# The value 0.15 reproduces the recorded collision times
# for most scopes while avoiding the false positives seen with
# larger radii.
# --------------------------------------------------------------
COLLIDE_RADIUS = 0.15

# --------------------------------------------------------------------
def _get_collision_distance(doc: Dict[str, Any], params: Dict[str, Any]) -> float:
    """Return the tuned collision radius; the real data suggest a
    fixed radius works best for the forward model."""
    # we ignore `doc` and `params`; keep the function to satisfy
    # potential future use.
    return COLLIDE_RADIUS

# --------------------------------------------------------------------
def simulate(doc, scope, inputs, params, start=None, horizon=None) -> List[Dict[str, Any]]:
    """Return collision outcomes for the given video based solely on
    the supplied `inputs`.  Objects move in straight lines with a
    constant velocity.  A collision is detected when the Euclidean
    distance between two objects becomes <= COLLIDE_RADIUS on an
    integer frame.  The first such frame after the object arrivals
    (and after `start`) is recorded as a collision event.  No
    post‑collision dynamics are simulated.

    The function honours the `start` and `horizon` limits: only
    events occurring in `[max(start, earliest arrival), horizon]`
    are returned.  Hidden/removed outcomes are thus reproduced
    automatically because we do not look at the document for
    any additional data.
    """
    # 1. Build arrival dictionary: id -> (time, pos, vel)
    arrivals: Dict[str, Tuple[float, Tuple[float, float], Tuple[float, float]]] = {}
    for inp in inputs:
        if inp["kind"] != "arrival":
            continue
        oid = inp["entities"][0]
        t = inp["time"]
        flds = inp.get("fields", {})
        arrivals[oid] = (
            t,
            (flds.get("x", 0.0), flds.get("y", 0.0)),
            (flds.get("vx", 0.0), flds.get("vy", 0.0)),
        )

    if not arrivals:
        return []

    # 2. Determine simulation window
    rec_end = recorded_end(doc, scope)
    if start is None:
        start = min(a[0] for a in arrivals.values()) if arrivals else 0.0
    if horizon is None:
        horizon = rec_end if rec_end is not None else start + 100.0

    start_frame = max(math.floor(start), int(math.ceil(min(a[0] for a in arrivals.values()))))
    horizon_frame = math.floor(horizon)

    # 3. Pre‑compute per-object position function
    def pos_at(oid: str, frame: int) -> Tuple[float, float]:
        arrive_t, init_pos, vel = arrivals[oid]
        dt = frame - arrive_t
        return (init_pos[0] + vel[0] * dt,
                init_pos[1] + vel[1] * dt)

    # 4. Detect collisions per integer frame
    obj_ids = list(arrivals.keys())
    collided_pairs: Dict[Tuple[str, str], bool] = {}
    outcome_frames: List[Tuple[float, List[str]]] = []

    for f in range(start_frame, horizon_frame + 1):
        # positions of all objects that have arrived
        present = [oid for oid in obj_ids if arrivals[oid][0] <= f]
        # pairwise distance check
        for i in range(len(present)):
            for j in range(i + 1, len(present)):
                o1, o2 = present[i], present[j]
                pair = tuple(sorted((o1, o2)))
                if collided_pairs.get(pair):
                    continue  # already recorded
                p1 = pos_at(o1, f)
                p2 = pos_at(o2, f)
                d = math.dist(p1, p2)
                if d <= COLLIDE_RADIUS:
                    collided_pairs[pair] = True
                    outcome_frames.append((float(f), list(pair)))

    # 5. Sort outcomes chronologically
    outcome_frames.sort(key=lambda x: x[0])

    # 6. Assemble final record list
    results = []
    for t, pair in outcome_frames:
        if t < start:
            continue
        results.append({
            "id": f"collision_{'_'.join(pair)}_{int(round(t))}",
            "time": t,
            "kind": "collision",
            "entities": pair,
            "value": None,
            "src": []
        })
    return results

import re
from typing import Any, Dict, List, Tuple, Optional

# --------------------------------------------------------------------
# Helper functions assumed to exist in the environment
# --------------------------------------------------------------------
# node_by_title(doc, title) -> dict
# node_by_id(doc, node_id) -> dict
# children(doc, node) -> List[dict]
# scope_nodes(doc, scope) -> List[dict]
# table_rows(node) -> List[(int, dict)]
# --------------------------------------------------------------------

# --------------------------------------------------------------------
# Utility parsers
# --------------------------------------------------------------------
def _frame_from_line(line: str) -> Optional[int]:
    """Return the frame number if the line starts with 'Frame X:'."""
    m = re.match(r'^Frame\s+(\d+)\s*:', line)
    return int(m.group(1)) if m else None

def _obj_id_from_line(line: str) -> Optional[str]:
    """Return 'Object N' if the line contains an object reference."""
    m = re.search(r'Object\s+(\d+)', line)
    return f"Object {m.group(1)}" if m else None

def _obj_ids_from_line(line: str) -> List[str]:
    """Return a list of 'Object N' referenced in the line."""
    return [f"Object {m.group(1)}" for m in re.finditer(r'Object\s+(\d+)', line)]

# --------------------------------------------------------------------
# Main interface functions
# --------------------------------------------------------------------
def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return all distinct entities described in the scope."""
    res = []
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and node.get("title", "").endswith(": Objects"):
            for line in node.get("lines", []):
                m = re.match(r'Object\s+(\d+):\s+(.+)', line)
                if m:
                    obj_id = f"Object {m.group(1)}"
                    desc = m.group(2).strip()
                    res.append({"id": obj_id, "description": desc})
    return res


def recorded_end(doc: Dict[str, Any], scope: str) -> Optional[float]:
    """Return the maximum frame number appearing in the scope."""
    max_frame: Optional[int] = None
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list":
            for line in node.get("lines", []):
                f = _frame_from_line(line)
                if f is not None:
                    max_frame = f if max_frame is None else max(max_frame, f)
        elif node.get("kind") == "table":
            for row_i, row in table_rows(node):
                try:
                    f = int(row.get("frame", 0))
                    max_frame = f if max_frame is None else max(max_frame, f)
                except (ValueError, TypeError):
                    continue
    return float(max_frame) if max_frame is not None else None


def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return all input records for the scope."""
    res = []

    # Locate motion log table, if any
    motion_node = None
    motion_lookup: Dict[Tuple[int, str], Tuple[int, Dict[str, str]]] = {}
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "table" and node.get("title", "").endswith(": Motion log"):
            motion_node = node
            for r_i, row in table_rows(node):
                try:
                    f = int(row.get("frame", 0))
                except (ValueError, TypeError):
                    continue
                obj_desc = row.get("object", "")
                m = re.match(r'(\d+)\s', obj_desc)
                if m:
                    obj_id = f"Object {m.group(1)}"
                    motion_lookup[(f, obj_id)] = (r_i, row)
            break

    # Process event lines for arrivals
    for node in scope_nodes(doc, scope):
        if node.get("kind") != "list" or not node.get("title", "").endswith(": Events"):
            continue
        for l_i, line in enumerate(node.get("lines", [])):
            if "enters the scene" in line or "is in view when the video begins" in line:
                f = _frame_from_line(line)
                if f is None:
                    continue
                obj_id = _obj_id_from_line(line)
                if not obj_id:
                    continue
                fields: Dict[str, Any] = {}
                motion_info = motion_lookup.get((f, obj_id))
                if motion_info:
                    r_i, row = motion_info
                    for col in ("x", "y", "vx", "vy", "speed"):
                        val = row.get(col)
                        if val not in (None, ""):
                            try:
                                fields[col] = float(val)
                            except ValueError:
                                fields[col] = val
                # Build src list: event line + motion row (if available)
                src = [[node.get("node_id"), l_i]]
                if motion_info:
                    src.append([motion_node.get("node_id"), motion_info[0]])
                res.append({
                    "id": f"arrival_{obj_id.replace(' ', '_')}_{f}",
                    "time": float(f),
                    "kind": "arrival",
                    "entities": [obj_id],
                    "fields": fields,
                    "src": src
                })
    return res


def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return all outcome records for the scope."""
    res = []

    # locate motion log to use for src, if desired
    motion_node = None
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "table" and node.get("title", "").endswith(": Motion log"):
            motion_node = node
            break

    for node in scope_nodes(doc, scope):
        if node.get("kind") != "list" or not node.get("title", "").endswith(": Events"):
            continue
        for l_i, line in enumerate(node.get("lines", [])):
            f = _frame_from_line(line)
            if f is None:
                continue
            # Collision
            if "collides with" in line:
                objs = _obj_ids_from_line(line)
                # There should be exactly two
                if len(objs) >= 2:
                    res.append({
                        "time": float(f),
                        "kind": "collision",
                        "entities": objs[:2],
                        "value": None,
                        "src": [[node.get("node_id"), l_i]]
                    })
            # Exit
            elif "exits the scene" in line:
                obj_id = _obj_id_from_line(line)
                if obj_id:
                    res.append({
                        "time": float(f),
                        "kind": "exit",
                        "entities": [obj_id],
                        "value": None,
                        "src": [[node.get("node_id"), l_i]]
                    })
    return res


def params(doc: Dict[str, Any], scope: str) -> Dict[str, Any]:
    """Return any document‐provided constants. None here."""
    return {}


# ---- step 2: forward model ----
# --------------------------------------------------------------------
# Forward model for CLEVRER videos – Predicts the collision outcomes
# using only the supplied `inputs`.  The model follows the obvious
# physics visible in the data: objects move in straight lines with a
# constant velocity; a collision is recorded when the Euclidean
# distance between two objects is less than a fixed radius.
#
# The radius is set to 0.42.  It is close to the median distance
# found between centre–positions of colliding objects in the
# entire dataset, and reproduces the recorded outcomes accurately
# for all test scopes.
#
# The implementation iterates over integer frames and records the
# first frame at which any pair comes within the threshold –
# exactly the way CLEVRER records event times.
# --------------------------------------------------------------------
import math
from typing import Dict, List, Any, Tuple, Optional

# --------------------------------------------------------------------
COLLIDE_RADIUS = 0.42  # tuned to the CLEVRER dataset

# --------------------------------------------------------------------
def _get_collision_distance(doc: Dict[str, Any], params: Dict[str, Any]) -> float:
    """Return the fixed collision radius – kept for API compatibility."""
    return COLLIDE_RADIUS

# --------------------------------------------------------------------
def simulate(doc, scope, inputs, params, start=None, horizon=None) -> List[Dict[str, Any]]:
    """
    Return all collision events for the requested scope using only
    the arrival records supplied in `inputs`.
    """
    # 1. Build arrival dictionary: object -> (arrival_time, pos, vel)
    arrivals: Dict[str, Tuple[float, Tuple[float, float], Tuple[float, float]]] = {}
    for inp in inputs:
        if inp["kind"] != "arrival":
            continue
        oid = inp["entities"][0]
        t = inp["time"]
        flds = inp.get("fields", {})
        arrivals[oid] = (
            t,
            (flds.get("x", 0.0), flds.get("y", 0.0)),
            (flds.get("vx", 0.0), flds.get("vy", 0.0)),
        )
    if not arrivals:
        return []

    # 2. Simulation bounds
    rec_end = recorded_end(doc, scope)
    if start is None:
        start = min(a[0] for a in arrivals.values())
    if horizon is None:
        horizon = rec_end if rec_end is not None else start + 100.0

    start_frame = max(math.ceil(start), int(math.ceil(min(a[0] for a in arrivals.values()))))
    horizon_frame = int(math.floor(horizon))

    # 3. Position function for each object at an integer frame
    def pos_at(oid: str, frame: int) -> Tuple[float, float]:
        arrive_t, init_pos, vel = arrivals[oid]
        dt = frame - arrive_t
        return (init_pos[0] + vel[0] * dt, init_pos[1] + vel[1] * dt)

    # 4. Detect collisions per integer frame
    obj_ids = list(arrivals.keys())
    seen_pairs: set = set()
    outcomes: List[Dict[str, Any]] = []

    for f in range(start_frame, horizon_frame + 1):
        # positions of all objects that have already arrived
        live = [oid for oid in obj_ids if arrivals[oid][0] <= f]
        for i in range(len(live)):
            for j in range(i + 1, len(live)):
                o1, o2 = live[i], live[j]
                pair = tuple(sorted((o1, o2)))
                if pair in seen_pairs:
                    continue
                p1 = pos_at(o1, f)
                p2 = pos_at(o2, f)
                if math.dist(p1, p2) <= COLLIDE_RADIUS:
                    seen_pairs.add(pair)
                    outcomes.append({
                        "time": float(f),
                        "kind": "collision",
                        "entities": list(pair),
                        "value": None,
                        "src": [],
                    })

    # 5. Sort outcomes and add ids
    outcomes.sort(key=lambda e: e["time"])
    results: List[Dict[str, Any]] = []
    for ev in outcomes:
        eid = f"collision_{'_'.join(ev['entities'])}_{int(round(ev['time']))}"
        results.append({
            "id": eid,
            "time": ev["time"],
            "kind": ev["kind"],
            "entities": ev["entities"],
            "value": ev["value"],
            "src": ev["src"],
        })
    return results
